-- Schema of the platform (§8). Enumerations are text + CHECK, identifiers are
-- UUID v7 generated by the application (reference data may use gen_random_uuid).
CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- ---------------------------------------------------------------- identity
CREATE TABLE roles (
    id          smallint PRIMARY KEY,
    code        text NOT NULL UNIQUE CHECK (code IN ('ADMIN','MANAGER','PROFESSIONAL','CLIENT')),
    description text NOT NULL DEFAULT ''
);

CREATE TABLE users (
    id                          uuid PRIMARY KEY,
    username                    citext NOT NULL UNIQUE,
    password_hash               text NOT NULL,
    status                      text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','SUSPENDED','DELETED')),
    status_reason               text,
    must_change_password        boolean NOT NULL DEFAULT false,
    recovery_codes_confirmed_at timestamptz,
    failed_login_count          int NOT NULL DEFAULT 0,
    locked_until                timestamptz,
    last_login_at               timestamptz,
    terms_version_accepted      text NOT NULL,
    terms_accepted_at           timestamptz NOT NULL,
    created_at                  timestamptz NOT NULL DEFAULT now(),
    updated_at                  timestamptz NOT NULL DEFAULT now(),
    deleted_at                  timestamptz
);
CREATE INDEX users_status_idx ON users (status);
CREATE INDEX users_username_trgm_idx ON users USING gin ((username::text) gin_trgm_ops);

CREATE TABLE user_roles (
    user_id    uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role_id    smallint NOT NULL REFERENCES roles(id) ON DELETE RESTRICT,
    granted_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, role_id)
);
CREATE INDEX user_roles_role_idx ON user_roles (role_id);

CREATE TABLE refresh_tokens (
    id                  uuid PRIMARY KEY,
    user_id             uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    family_id           uuid NOT NULL,
    token_hash          bytea NOT NULL UNIQUE,
    parent_id           uuid REFERENCES refresh_tokens(id) ON DELETE SET NULL,
    expires_at          timestamptz NOT NULL,
    absolute_expires_at timestamptz NOT NULL,
    revoked_at          timestamptz,
    revoked_reason      text CHECK (revoked_reason IN ('LOGOUT','ROTATED','REUSE_DETECTED','PASSWORD_RECOVERED','ADMIN_PASSWORD_RESET','PASSWORD_CHANGED','SUSPENDED','ADMIN','DELETED')),
    user_agent          varchar(255) NOT NULL DEFAULT '',
    ip_hash             text NOT NULL DEFAULT '',
    created_at          timestamptz NOT NULL DEFAULT now(),
    last_used_at        timestamptz
);
CREATE INDEX refresh_tokens_family_idx ON refresh_tokens (family_id);
CREATE INDEX refresh_tokens_user_idx ON refresh_tokens (user_id) WHERE revoked_at IS NULL;
CREATE INDEX refresh_tokens_expiry_idx ON refresh_tokens (absolute_expires_at);

CREATE TABLE recovery_codes (
    id         uuid PRIMARY KEY,
    user_id    uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    code_hash  bytea NOT NULL,
    used_at    timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (user_id, code_hash)
);

-- ---------------------------------------------------------------- reference data
CREATE TABLE regions (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    country_code char(2) NOT NULL DEFAULT 'BE',
    name         text NOT NULL,
    slug         text NOT NULL UNIQUE,
    parent_id    uuid REFERENCES regions(id) ON DELETE RESTRICT,
    kind         text NOT NULL CHECK (kind IN ('REGION','CITY')),
    is_active    boolean NOT NULL DEFAULT true,
    CHECK ((kind = 'REGION' AND parent_id IS NULL) OR (kind = 'CITY' AND parent_id IS NOT NULL))
);
CREATE INDEX regions_parent_idx ON regions (parent_id);
CREATE INDEX regions_name_trgm_idx ON regions USING gin (name gin_trgm_ops);

CREATE TABLE categories (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    parent_id   uuid REFERENCES categories(id) ON DELETE RESTRICT,
    slug        text NOT NULL UNIQUE,
    name        text NOT NULL,
    description text NOT NULL DEFAULT '',
    is_active   boolean NOT NULL DEFAULT true,
    position    int NOT NULL DEFAULT 0
);
CREATE INDEX categories_parent_idx ON categories (parent_id);

-- ---------------------------------------------------------------- establishments
CREATE TABLE establishments (
    id                  uuid PRIMARY KEY,
    manager_user_id     uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE RESTRICT,
    slug                text NOT NULL UNIQUE,
    display_name        text NOT NULL DEFAULT '',
    legal_name          text NOT NULL DEFAULT '',
    company_number      text UNIQUE,
    approval_number     text UNIQUE,
    description         text NOT NULL DEFAULT '' CHECK (char_length(description) <= 5000),
    opening_hours       jsonb NOT NULL DEFAULT '{}'::jsonb,
    region_id           uuid REFERENCES regions(id) ON DELETE RESTRICT,
    city_id             uuid REFERENCES regions(id) ON DELETE RESTRICT,
    address             text,
    address_public      boolean NOT NULL DEFAULT false,
    verification_status text NOT NULL DEFAULT 'DRAFT' CHECK (verification_status IN ('DRAFT','PENDING','VERIFIED','REJECTED')),
    verification_note   text,
    submitted_at        timestamptz,
    verified_at         timestamptz,
    verified_by         uuid REFERENCES users(id) ON DELETE SET NULL,
    is_hidden           boolean NOT NULL DEFAULT false,
    hidden_reason       text,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    deleted_at          timestamptz
);
CREATE INDEX establishments_region_idx ON establishments (region_id);
CREATE INDEX establishments_city_idx ON establishments (city_id);
CREATE INDEX establishments_verification_idx ON establishments (verification_status);
CREATE INDEX establishments_name_trgm_idx ON establishments USING gin (display_name gin_trgm_ops);

CREATE TABLE establishment_contacts (
    id                    uuid PRIMARY KEY,
    establishment_id      uuid NOT NULL REFERENCES establishments(id) ON DELETE CASCADE,
    type                  text NOT NULL CHECK (type IN ('PHONE','WHATSAPP','TELEGRAM','INSTAGRAM','FACEBOOK','WEBSITE','OTHER')),
    value                 text NOT NULL,
    visibility            text NOT NULL CHECK (visibility IN ('PUBLIC','CLIENTS','HIDDEN')),
    is_verification_phone boolean NOT NULL DEFAULT false,
    position              int NOT NULL DEFAULT 0,
    UNIQUE (establishment_id, type, value)
);
CREATE UNIQUE INDEX establishment_contacts_verification_idx ON establishment_contacts (establishment_id) WHERE is_verification_phone;

-- ---------------------------------------------------------------- profiles
CREATE TABLE professional_profiles (
    id                   uuid PRIMARY KEY,
    establishment_id     uuid NOT NULL REFERENCES establishments(id) ON DELETE CASCADE,
    user_id              uuid UNIQUE REFERENCES users(id) ON DELETE SET NULL,
    slug                 text NOT NULL UNIQUE,
    display_name         text NOT NULL,
    headline             text NOT NULL DEFAULT '' CHECK (char_length(headline) <= 120),
    description          text NOT NULL DEFAULT '' CHECK (char_length(description) <= 5000),
    height_cm            smallint CHECK (height_cm BETWEEN 120 AND 230),
    weight_kg            smallint CHECK (weight_kg BETWEEN 35 AND 250),
    hair_color           text CHECK (hair_color IN ('BLONDE','BROWN','BLACK','RED','GREY','OTHER')),
    eye_color            text CHECK (eye_color IN ('BLUE','GREEN','BROWN','HAZEL','GREY','BLACK','OTHER')),
    body_type            text CHECK (body_type IN ('SLIM','ATHLETIC','AVERAGE','CURVY','PLUS_SIZE','MUSCULAR')),
    languages            text[] NOT NULL DEFAULT '{}',
    extra_attributes     jsonb NOT NULL DEFAULT '{}'::jsonb,
    birth_date_attested  date,
    employment_reference text,
    attested_at          timestamptz,
    attested_by          uuid REFERENCES users(id) ON DELETE SET NULL,
    status               text NOT NULL CHECK (status IN ('PENDING_APPROVAL','DRAFT','ACTIVE','ARCHIVED')),
    is_hidden            boolean NOT NULL DEFAULT false,
    hidden_reason        text,
    price_from_cents     bigint,
    is_published         boolean NOT NULL DEFAULT false,
    published_at         timestamptz,
    last_edited_by       uuid REFERENCES users(id) ON DELETE SET NULL,
    created_at           timestamptz NOT NULL DEFAULT now(),
    updated_at           timestamptz NOT NULL DEFAULT now(),
    deleted_at           timestamptz,
    CHECK ((attested_at IS NULL) = (birth_date_attested IS NULL))
);
CREATE INDEX profiles_establishment_status_idx ON professional_profiles (establishment_id, status);
CREATE INDEX profiles_published_idx ON professional_profiles (id) WHERE is_published;
CREATE INDEX profiles_pub_price_idx ON professional_profiles (is_published, price_from_cents);
CREATE INDEX profiles_pub_birth_idx ON professional_profiles (is_published, birth_date_attested);
CREATE INDEX profiles_pub_recent_idx ON professional_profiles (is_published, published_at DESC);
CREATE INDEX profiles_languages_idx ON professional_profiles USING gin (languages);

CREATE TABLE profile_photos (
    id          uuid PRIMARY KEY,
    profile_id  uuid NOT NULL REFERENCES professional_profiles(id) ON DELETE CASCADE,
    storage_key text NOT NULL UNIQUE,
    is_primary  boolean NOT NULL DEFAULT false,
    position    int NOT NULL DEFAULT 0,
    width       int NOT NULL,
    height      int NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX profile_photos_primary_idx ON profile_photos (profile_id) WHERE is_primary;
CREATE INDEX profile_photos_profile_idx ON profile_photos (profile_id, position);

CREATE TABLE profile_contacts (
    id         uuid PRIMARY KEY,
    profile_id uuid NOT NULL REFERENCES professional_profiles(id) ON DELETE CASCADE,
    type       text NOT NULL CHECK (type IN ('PHONE','WHATSAPP','TELEGRAM','INSTAGRAM','FACEBOOK','WEBSITE','OTHER')),
    value      text NOT NULL,
    visibility text NOT NULL CHECK (visibility IN ('PUBLIC','CLIENTS','HIDDEN')),
    position   int NOT NULL DEFAULT 0,
    UNIQUE (profile_id, type, value)
);

CREATE TABLE profile_rates (
    id               uuid PRIMARY KEY,
    profile_id       uuid NOT NULL REFERENCES professional_profiles(id) ON DELETE CASCADE,
    label            text NOT NULL CHECK (char_length(label) BETWEEN 1 AND 60),
    duration_minutes int CHECK (duration_minutes BETWEEN 1 AND 1440),
    amount_cents     bigint NOT NULL CHECK (amount_cents > 0),
    currency         char(3) NOT NULL DEFAULT 'EUR',
    position         int NOT NULL DEFAULT 0
);
CREATE INDEX profile_rates_profile_idx ON profile_rates (profile_id);

CREATE TABLE professional_categories (
    profile_id  uuid NOT NULL REFERENCES professional_profiles(id) ON DELETE CASCADE,
    category_id uuid NOT NULL REFERENCES categories(id) ON DELETE RESTRICT,
    PRIMARY KEY (profile_id, category_id)
);
CREATE INDEX professional_categories_category_idx ON professional_categories (category_id, profile_id);

-- ---------------------------------------------------------------- clients
CREATE TABLE favorites (
    client_user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    profile_id     uuid NOT NULL REFERENCES professional_profiles(id) ON DELETE CASCADE,
    created_at     timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (client_user_id, profile_id)
);
CREATE INDEX favorites_profile_idx ON favorites (profile_id);

-- ---------------------------------------------------------------- billing
CREATE TABLE subscription_plans (
    id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    code                 text NOT NULL UNIQUE,
    name                 text NOT NULL,
    amount_cents         bigint NOT NULL CHECK (amount_cents > 0),
    currency             char(3) NOT NULL DEFAULT 'EUR',
    interval_days        int NOT NULL DEFAULT 30 CHECK (interval_days > 0),
    trial_days           int NOT NULL DEFAULT 0 CHECK (trial_days >= 0),
    grace_days           int NOT NULL DEFAULT 3 CHECK (grace_days >= 0),
    max_pending_profiles int NOT NULL DEFAULT 20 CHECK (max_pending_profiles >= 0),
    max_active_profiles  int CHECK (max_active_profiles > 0),
    is_active            boolean NOT NULL DEFAULT true,
    created_at           timestamptz NOT NULL DEFAULT now(),
    updated_at           timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE subscriptions (
    id                   uuid PRIMARY KEY,
    establishment_id     uuid NOT NULL REFERENCES establishments(id) ON DELETE RESTRICT,
    plan_id              uuid NOT NULL REFERENCES subscription_plans(id) ON DELETE RESTRICT,
    status               text NOT NULL CHECK (status IN ('TRIALING','ACTIVE','PAST_DUE','CANCELED','INCOMPLETE')),
    current_period_start timestamptz,
    current_period_end   timestamptz,
    grace_until          timestamptz,
    cancel_at_period_end boolean NOT NULL DEFAULT false,
    canceled_at          timestamptz,
    provider             text NOT NULL,
    created_at           timestamptz NOT NULL DEFAULT now(),
    updated_at           timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX subscriptions_establishment_idx ON subscriptions (establishment_id);
CREATE UNIQUE INDEX subscriptions_current_idx ON subscriptions (establishment_id)
    WHERE status IN ('TRIALING','ACTIVE','PAST_DUE','INCOMPLETE');
CREATE INDEX subscriptions_period_end_idx ON subscriptions (status, current_period_end);

CREATE TABLE payments (
    id                  uuid PRIMARY KEY,
    subscription_id     uuid NOT NULL REFERENCES subscriptions(id) ON DELETE RESTRICT,
    establishment_id    uuid NOT NULL REFERENCES establishments(id) ON DELETE RESTRICT,
    period_start        timestamptz,
    period_end          timestamptz,
    amount_cents        bigint NOT NULL CHECK (amount_cents > 0),
    currency            char(3) NOT NULL,
    provider            text NOT NULL,
    provider_invoice_id text UNIQUE,
    provider_payment_id text UNIQUE,
    pay_currency        text,
    pay_amount_expected numeric(36,18),
    pay_amount_received numeric(36,18),
    status              text NOT NULL CHECK (status IN ('PENDING','CONFIRMING','PARTIAL','PAID','FAILED','EXPIRED','REFUNDED')),
    provider_status     text,
    paid_at             timestamptz,
    invoice_url         text,
    expires_at          timestamptz,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX payments_subscription_idx ON payments (subscription_id);
CREATE INDEX payments_establishment_idx ON payments (establishment_id, created_at DESC);
CREATE INDEX payments_open_idx ON payments (status, created_at) WHERE status IN ('PENDING','CONFIRMING');

CREATE TABLE invoices (
    id               uuid PRIMARY KEY,
    number           text NOT NULL UNIQUE,
    payment_id       uuid NOT NULL UNIQUE REFERENCES payments(id) ON DELETE RESTRICT,
    establishment_id uuid NOT NULL REFERENCES establishments(id) ON DELETE RESTRICT,
    amount_cents     bigint NOT NULL,
    currency         char(3) NOT NULL,
    issued_at        timestamptz NOT NULL,
    billing_snapshot jsonb NOT NULL,
    pdf_storage_key  text
);
CREATE INDEX invoices_establishment_idx ON invoices (establishment_id, issued_at DESC);

CREATE TABLE payment_provider_events (
    id               uuid PRIMARY KEY,
    provider         text NOT NULL,
    event_key        text NOT NULL,
    payload          jsonb NOT NULL,
    signature_valid  boolean NOT NULL,
    processed_at     timestamptz,
    processing_error text,
    received_at      timestamptz NOT NULL DEFAULT now(),
    UNIQUE (provider, event_key)
);

-- ---------------------------------------------------------------- audit
CREATE TABLE audit_logs (
    id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    occurred_at   timestamptz NOT NULL DEFAULT now(),
    actor_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
    actor_role    text,
    action        text NOT NULL,
    category      text NOT NULL CHECK (category IN ('SECURITY','ADMIN','BILLING','ESTABLISHMENT','PROFILE','AUTH')),
    severity      text NOT NULL CHECK (severity IN ('INFO','WARN','CRITICAL')),
    target_type   text,
    target_id     text,
    ip_hash       text,
    user_agent    varchar(255),
    request_id    text,
    metadata      jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX audit_logs_occurred_brin ON audit_logs USING brin (occurred_at);
CREATE INDEX audit_logs_category_idx ON audit_logs (category, id DESC);
CREATE INDEX audit_logs_target_idx ON audit_logs (target_type, target_id);
CREATE INDEX audit_logs_actor_idx ON audit_logs (actor_user_id);
